#!/usr/bin/env python3
"""
Round 107c tiles patch (28 September 2026): the source file for
scripts/inpe_fire.py, INPE's 2023 fire detections in South America from the
owner's Attacks On Activists collection (attacks/inpe_fire_foci_2023.geojson.gz,
332,432 fires, every field kept).

Whole files, written only where they differ. Run from the repository root.
"""
import base64, gzip, pathlib

FILES = {'attacks/inpe_fire_foci_2023.geojson.gz': ('', False)}

if not pathlib.Path("scripts").is_dir():
    raise SystemExit("round107c: scripts/ not found; run from the culprits-tiles-more root")
changed = []
for path, (b64, gz) in FILES.items():
    p = pathlib.Path(path)
    new = base64.b64decode(b64)
    if gz:
        new = gzip.decompress(new)
    if p.exists() and p.read_bytes() == new:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(new)
    changed.append(path)
print("round107c: " + (", ".join(changed) if changed else "nothing to change (already applied)"))
